function Maze2DSounds.PlayMusic( music_ )
    assert( type(music_) == "table" )
    if music_.type == "BGM" then 
        CriWareUtils.PlayMusic( music_.sheetPath, music_.cueName )

    elseif music_.type == "SFX" then
        CriWareUtils.PlaySe( music_.sheetPath, music_.cueName )

    end
end


function Maze2DSounds.Stop( music_ )
    assert( type(music_) == "table" )
    if music_.type == "BGM" then 
        -- todo: 啥也不做

    elseif music_.type == "SFX" then
        CriWareUtils.Stop( music_.sheetPath, music_.cueName )
    end
end




